import {feed,assess,validateClosure} from './model.mjs';
const $=id=>document.getElementById(id);let inspection=null,crew=null;
const crews=[{id:'a',name:'Equipo Verde',skill:'Plomería',fee:450,eta:'2-4 h'},{id:'b',name:'Equipo Norte',skill:'Plomería',fee:600,eta:'1-2 h'},{id:'c',name:'Equipo Señal',skill:'Telemetría',fee:350,eta:'4-6 h'}];
function draw(kind){const data=feed(kind),w=550,h=185,p=25,max=22;const points=(key)=>data.filter(d=>d[key]!==null).map(d=>`${p+d.h/23*(w-p*2)},${h-p-d[key]/max*(h-p*2)}`).join(' ');$('chart').innerHTML=`<svg viewBox="0 0 ${w} ${h}" aria-hidden="true"><g fill="#809184" font-size="9" font-family="sans-serif">${[0,10,20].map(v=>`<text x="0" y="${h-p-v/max*(h-p*2)+3}">${v}</text><path d="M${p} ${h-p-v/max*(h-p*2)}H${w-p}" stroke="#e5eae1"/>`).join('')}<text x="25" y="182">00:00</text><text x="265" y="182">12:00</text><text x="498" y="182">23:00</text></g><polyline points="${points('baseline')}" fill="none" stroke="#a3b8a5" stroke-width="2" stroke-dasharray="5 5"/><polyline points="${points('flow')}" fill="none" stroke="#087b6d" stroke-width="3" stroke-linejoin="round"/></svg>`;}
function render(){const k=$('scenario').value,a=assess(k);draw(k);$('assessmentTitle').textContent=a.title;$('assessmentText').textContent=a.text;$('stateMetric').textContent={review:'Por revisar',normal:'Sin desvío',unknown:'Sin señal',context:'Falta contexto'}[a.state];$('statusTag').textContent={review:'REVISIÓN RECOMENDADA',normal:'SOLO ESTE ESCENARIO',unknown:'DATOS INSUFICIENTES',context:'REVISIÓN DE CONTEXTO'}[a.state];$('nextStep').textContent={review:'Verifica el suministro y revisa la instalación antes de afirmar que hay una fuga.',normal:'Continúa observando. Si hay un problema visible, abre una revisión manual.',unknown:'Verifica alimentación y comunicación del sensor. No uses este tramo para inferir pérdidas.',context:'Confirma el horario de suministro y el llenado de cisterna. Compara lecturas bajo condiciones similares.'}[a.state];}
$('scenario').addEventListener('change',render);
$('open').addEventListener('click',()=>{inspection={scenario:$('scenario').value,status:'open',synthetic:true};crew=null;$('closed').hidden=true;$('ticket').hidden=false;$('ticketIntro').textContent='Revisión local abierta. Elige quién revisaría y registra evidencia inventada para probar el cierre.';$('ticketStatus').textContent='Abierta · ejemplo';$('ticketScenario').textContent=$('scenario').selectedOptions[0].textContent;$('closure').reset();$('error').textContent='';const skill=inspection.scenario==='offline'?'Telemetría':'Plomería';$('crews').replaceChildren();crews.filter(c=>c.skill===skill).forEach(c=>{const label=document.createElement('label');label.className='crew';const radio=document.createElement('input');radio.type='radio';radio.name='crew';radio.value=c.id;radio.addEventListener('change',()=>crew=c);const title=document.createElement('strong');title.textContent=c.name;const desc=document.createElement('p');desc.textContent=`${c.skill} · $${c.fee} MXN supuestos · ${c.eta} supuesto`;label.append(radio,title,desc);$('crews').append(label);});$('revision').scrollIntoView({behavior:'smooth'});});
$('closure').addEventListener('submit',e=>{e.preventDefault();const v={cause:$('cause').value,before:$('before').value,after:$('after').value,note:$('note').value};if(!inspection||!crew||!validateClosure(v)){$('error').textContent='Elige una cuadrilla y completa: causa (8-180 caracteres), ambas lecturas no negativas y evidencia (12-500 caracteres).';return;}inspection={...inspection,status:'closed',crew:crew.name,evidence:v,limitations:'Datos simulados; sin certificación de reparación ni ahorro; sin despacho real.'};$('ticket').hidden=true;$('closed').hidden=false;$('ticketStatus').textContent='Cerrada · ejemplo';$('ticketIntro').textContent='Registro completo, conservado solo en esta sesión.';$('result').textContent=`${v.cause}. Antes: ${v.before} L/min. Después: ${v.after} L/min. Evidencia: ${v.note}`;});
$('export').addEventListener('click',()=>{const b=new Blob([JSON.stringify(inspection,null,2)],{type:'application/json'});const url=URL.createObjectURL(b);const a=document.createElement('a');a.href=url;a.download='revision-DEMO.json';a.click();URL.revokeObjectURL(url);});render();
